import { Component } from '@angular/core';
import { ArtikalService } from '../artikal.service';
import jwt_decode from 'jwt-decode'; // Uvezi jwt-decode

@Component({
  selector: 'app-izmeni-artikle',
  templateUrl: './izmeni-artikle.component.html',
  styleUrls: ['./izmeni-artikle.component.css']
})
export class IzmeniArtikleComponent {
  artikli: any[] = [];
  email: string = '';

  constructor(private artikalService: ArtikalService) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.email = decodedToken.email; // Assuming the token contains the email
      this.fetchArtikli();
    }
  }

  fetchArtikli() {
    this.artikalService.getArtikliByStoreEmail(this.email).subscribe(
      (response) => {
        this.artikli = response.artikli;
      },
      (error) => {
        console.error('Greška pri dohvatanju artikala:', error);
      }
    );
  }

  onSubmit() {
    let updatedCount = 0;

    this.artikli.forEach((artikal, index) => {
      this.artikalService.updateArtikal(artikal._id, artikal).subscribe(
        (response) => {
          updatedCount++;
          if (updatedCount === this.artikli.length) {
            alert('Sve izmene su uspešno sačuvane!');
          }
        },
        (error) => {
          console.error(`Greška pri ažuriranju artikla ${index + 1}:`, error);
        }
      );
    });
  }

  getArtikalImage(imagePath: string): string {
    return `http://localhost:4000/${imagePath}`;
  }

}
